CREATE OR REPLACE FUNCTION public.listing_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TABLE public.listing_profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', store_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.listing_profiles TO authenticated; GRANT ALL ON public.listing_profiles TO service_role;
ALTER TABLE public.listing_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_profile ON public.listing_profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TRIGGER listing_profile_touch BEFORE UPDATE ON public.listing_profiles FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE OR REPLACE FUNCTION public.create_listing_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.listing_profiles(id,display_name,store_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',''),coalesce(NEW.raw_user_meta_data->>'store_name','')) ON CONFLICT(id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_listing_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_listing_profile();
CREATE TABLE public.listing_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, facts jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.listing_products TO authenticated; GRANT ALL ON public.listing_products TO service_role;
ALTER TABLE public.listing_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_products ON public.listing_products FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER listing_product_touch BEFORE UPDATE ON public.listing_products FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE TABLE public.listing_variations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), product_id uuid NOT NULL REFERENCES public.listing_products(id) ON DELETE CASCADE, label text NOT NULL DEFAULT 'Original', reference_paths jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.listing_variations TO authenticated; GRANT ALL ON public.listing_variations TO service_role;
ALTER TABLE public.listing_variations ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_variations ON public.listing_variations FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.listing_products p WHERE p.id=product_id AND p.user_id=auth.uid()));
CREATE TRIGGER listing_variation_touch BEFORE UPDATE ON public.listing_variations FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE TABLE public.listing_marketplace_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), marketplace text NOT NULL, title_limit integer NOT NULL, description_limit integer NOT NULL, source text NOT NULL DEFAULT 'Configuração provisória da loja', verified_at date, rules text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,marketplace), CHECK(title_limit BETWEEN 1 AND 1000), CHECK(description_limit BETWEEN 100 AND 50000));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.listing_marketplace_rules TO authenticated; GRANT ALL ON public.listing_marketplace_rules TO service_role;
ALTER TABLE public.listing_marketplace_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_rules ON public.listing_marketplace_rules FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER listing_rules_touch BEFORE UPDATE ON public.listing_marketplace_rules FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE TABLE public.intelligent_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), product_id uuid NOT NULL REFERENCES public.listing_products(id) ON DELETE CASCADE, variation_id uuid NOT NULL REFERENCES public.listing_variations(id) ON DELETE CASCADE, marketplace text NOT NULL, studio text NOT NULL DEFAULT 'professional', image_count integer NOT NULL DEFAULT 6 CHECK(image_count IN(6,7,8)), content jsonb NOT NULL DEFAULT '{}'::jsonb, rule_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.intelligent_listings TO authenticated; GRANT ALL ON public.intelligent_listings TO service_role;
ALTER TABLE public.intelligent_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_intelligent_listings ON public.intelligent_listings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.listing_products p WHERE p.id=product_id AND p.user_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.listing_variations v WHERE v.id=variation_id AND v.product_id=product_id AND v.user_id=auth.uid()));
CREATE TRIGGER intelligent_listing_touch BEFORE UPDATE ON public.intelligent_listings FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE TABLE public.listing_generated_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES public.intelligent_listings(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position BETWEEN 0 AND 7), path text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(listing_id,position));
GRANT SELECT, UPDATE, DELETE ON public.listing_generated_images TO authenticated; GRANT ALL ON public.listing_generated_images TO service_role;
ALTER TABLE public.listing_generated_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_images_read ON public.listing_generated_images FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_listing_images_update ON public.listing_generated_images FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY own_listing_images_delete ON public.listing_generated_images FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER listing_images_touch BEFORE UPDATE ON public.listing_generated_images FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE TABLE public.listing_generation_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES public.intelligent_listings(id) ON DELETE CASCADE, operation text NOT NULL, position integer NOT NULL DEFAULT -1, revision uuid NOT NULL, status text NOT NULL DEFAULT 'queued', lease_until timestamptz, pause_reason text, output jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(listing_id,operation,position,revision));
GRANT SELECT ON public.listing_generation_jobs TO authenticated; GRANT ALL ON public.listing_generation_jobs TO service_role;
ALTER TABLE public.listing_generation_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_listing_jobs_read ON public.listing_generation_jobs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER listing_jobs_touch BEFORE UPDATE ON public.listing_generation_jobs FOR EACH ROW EXECUTE FUNCTION public.listing_touch_updated_at();
CREATE INDEX listing_jobs_owner ON public.listing_generation_jobs(user_id,listing_id);
CREATE OR REPLACE FUNCTION public.claim_listing_job(job_id uuid, owner_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE count_updated integer; BEGIN UPDATE public.listing_generation_jobs SET status='running',lease_until=now()+interval '10 minutes' WHERE id=job_id AND user_id=owner_id AND status='queued'; GET DIAGNOSTICS count_updated=ROW_COUNT; RETURN count_updated=1; END; $$;
REVOKE ALL ON FUNCTION public.claim_listing_job(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_listing_job(uuid,uuid) TO service_role;